#!/bin/bash
# Install Skyline.command — double-click in iCloud Drive/Skyline on any of Brian's Macs.
# Installs the Skyline.zip that sits next to this file into /Applications, after checking it is signed
# by the build Mac's "Skyline Local Signing" certificate (same check as scripts/install-verified.sh).
# First time on a Mac: right-click (or Control-click) this file › Open › Open, because macOS blocks
# double-clicking a downloaded script once. Generated by build-app.sh; don't edit the iCloud copy.
HERE="$(cd "$(dirname "$0")" && pwd)"
ZIPFILE="$HERE/Skyline.zip"
echo "Skyline installer"
[[ -f "$HERE/VERSION.txt" ]] && sed 's/^/  iCloud: /' "$HERE/VERSION.txt"
# Make iCloud download the zip (and VERSION.txt) if this Mac only has placeholders, then wait for it.
brctl download "$HERE/VERSION.txt" >/dev/null 2>&1 || true
brctl download "$ZIPFILE" >/dev/null 2>&1 || true
echo "  Waiting for iCloud to download Skyline.zip…"
for _ in $(seq 1 300); do
  if [[ -f "$ZIPFILE" ]] && ! stat -f %Sf "$ZIPFILE" | grep -q dataless && zipinfo -1 "$ZIPFILE" >/dev/null 2>&1; then break; fi
  sleep 1
done
zipinfo -1 "$ZIPFILE" >/dev/null 2>&1 || { echo "Skyline.zip didn't download from iCloud within 5 minutes. Check iCloud Drive, then run this again." >&2; exit 1; }
set -- "$ZIPFILE"
# ---- verified install (scripts/install-verified.sh) ----
